#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization.
 *
 * The code has been optimized for:
 *  - better cache locality (row pointers),
 *  - fewer redundant computations (skip unused diagonal initialization),
 *  - reduced arithmetic in Gram matrix construction by exploiting symmetry,
 *  - more efficient copy-back using memcpy.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Local restricted pointer to help the compiler with alias analysis. */
  DATA_TYPE (*restrict a)[n] = A;

  /* Initialize A as in the original version, but avoid computing the
   * diagonal value that will be immediately overwritten by 1.0.
   */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = a[i];

      /* Strictly lower triangular part (j < i). */
      for (j = 0; j < i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + (DATA_TYPE)1;

      /* Diagonal is explicitly set to 1. */
      Ai[i] = (DATA_TYPE)1;

      /* Strictly upper triangular part (j > i). */
      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;
    }

  /* Make the matrix positive semi-definite.
   * This computes B = A * A^T (Gram matrix) and copies it back to A.
   * We exploit symmetry to halve the arithmetic: only the upper
   * triangle of B is accumulated, then mirrored to the lower triangle.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Zero-initialize B with good row-major locality. */
  for (r = 0; r < n; ++r) {
    DATA_TYPE *restrict Brow = (POLYBENCH_ARRAY(B))[r];
    for (s = 0; s < n; ++s)
      Brow[s] = (DATA_TYPE)0;
  }

  /* Accumulate only the upper triangle of B (r <= s):
   *   B[r][s] = sum_t A[r][t] * A[s][t]
   */
  for (t = 0; t < n; ++t) {
    for (r = 0; r < n; ++r) {
      const DATA_TYPE Ar_t = a[r][t];
      DATA_TYPE *restrict Brow = (POLYBENCH_ARRAY(B))[r];
      for (s = r; s < n; ++s) {
        Brow[s] += Ar_t * a[s][t];
      }
    }
  }

  /* Use symmetry B[s][r] = B[r][s] to fill the lower triangle.
   * This preserves the exact numerical result of the original code,
   * since the original computed both B[r][s] and B[s][r] with the
   * same sequence of floating-point operations.
   */
  for (r = 0; r < n; ++r) {
    for (s = r + 1; s < n; ++s) {
      (POLYBENCH_ARRAY(B))[s][r] = (POLYBENCH_ARRAY(B))[r][s];
    }
  }

  /* Copy B back into A row by row. */
  for (r = 0; r < n; ++r) {
    DATA_TYPE *restrict Ar = a[r];
    DATA_TYPE *restrict Br = (POLYBENCH_ARRAY(B))[r];
    /* memcpy keeps the exact element-wise contents. */
    memcpy(Ar, Br, (size_t)n * sizeof(DATA_TYPE));
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use a restricted row-major pointer for A to improve alias analysis.
 *  - Hoist A[i][*] row pointer out of inner loops.
 *  - Use a scalar accumulator for the inner dot-products to reduce
 *    repeated loads/stores of A[i][j].
 *  - Provide an OpenMP 'simd' hint for potential vectorization of the
 *    inner k-loops (ignored when OpenMP is not enabled).
 */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restricted pointer to the 2D array.
   * After parameter adjustment, A has type DATA_TYPE (*)[n].
   */
  DATA_TYPE (*restrict a)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Pointer to the current row for better cache locality. */
    DATA_TYPE *restrict Ai = a[i];

    /* Compute L(i, j) for j < i (strictly lower triangular part).
     *
     * Original:
     *   for (j = 0; j < i; j++) {
     *     for (k = 0; k < j; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *     A[i][j] /= A[j][j];
     *   }
     */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];

      /* sum -= A[i][k] * A[k][j] for k = 0..j-1 */
#if defined(_OPENMP)
#pragma omp simd reduction(-:sum)
#endif
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * a[k][j];
      }

      Ai[j] = sum / a[j][j];
    }

    /* Compute U(i, j) for j >= i (diagonal and upper triangular part).
     *
     * Original:
     *   for (j = i; j < _PB_N; j++) {
     *     for (k = 0; k < i; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *   }
     */
    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = Ai[j];

      /* sum -= A[i][k] * A[k][j] for k = 0..i-1 */
#if defined(_OPENMP)
#pragma omp simd reduction(-:sum)
#endif
      for (k = 0; k < i; k++) {
        sum -= Ai[k] * a[k][j];
      }

      Ai[j] = sum;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
