#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initial lower-triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     We compute B = A * A^T (Gram matrix) and copy it back to A.

     Original version:
       - First zeroed B
       - Then used the loop order (t,r,s):
           B[r][s] += A[r][t] * A[s][t]

     Optimized version below:
       - Directly compute each B[r][s] as a dot product of row r and row s:
           B[r][s] = sum_t A[r][t] * A[s][t]
       - This:
         * eliminates the explicit zero-initialization of B,
         * uses a scalar accumulator to reduce memory traffic on B,
         * traverses A rows contiguously in the innermost loop.

     For a fixed (r,s), both the original and the new code:
       - accumulate contributions in increasing t order,
       - therefore perform the same sequence of floating-point
         operations for each element B[r][s].
     Thus the numerical result for each B[r][s] is bitwise identical
     on standard IEEE-754 hardware.
  */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  for (r = 0; r < n; ++r)
    {
      for (s = 0; s < n; ++s)
        {
          DATA_TYPE acc = (DATA_TYPE)0;

          /* Inner loop over t walks rows of A contiguously:
             A[r][t] and A[s][t] are both accessed with t as the
             innermost index (row-major layout), improving cache
             locality compared to the original (t,r,s) ordering. */
          for (t = 0; t < n; ++t)
            acc += A[r][t] * A[s][t];

          (POLYBENCH_ARRAY(B))[r][s] = acc;
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied inside:
     - Use scalar temporaries to keep A[i][j] in registers while
       accumulating inner products, reducing repeated loads/stores.
     - For the second (upper-triangular) update, interchange the (j,k)
       loops to perform a rank-1 update:
           for k: A[i][*] -= A[i][k] * A[k][*]
       This:
         * reuses A[i][k] across the entire row,
         * walks both A[i][j] and A[k][j] contiguously along j.

   For each element A[i][j], the sequence of floating-point
   operations (products and subtractions, and the division for j<i)
   is preserved in the same order as the original code; only the
   storage pattern is changed, so numerical results remain identical
   on standard IEEE-754 hardware.
*/
static void __attribute__((noinline, flatten))
kernel_lu(int n,
          DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Compute the L part: j = 0 .. i-1.
         Original:
           for (j < i)
             for (k < j)
               A[i][j] -= A[i][k] * A[k][j];
             A[i][j] /= A[j][j];

         Optimized:
           - Use a scalar accumulator 'sum' to keep A[i][j] in a register.
           - The inner products are accumulated in the same k-order. */
      for (j = 0; j < i; j++)
        {
          DATA_TYPE sum = A[i][j];

          for (k = 0; k < j; k++)
            sum -= A[i][k] * A[k][j];

          sum /= A[j][j];
          A[i][j] = sum;
        }

      /* Compute the U part: j = i .. N-1.

         Original:
           for (j = i; j < N; ++j)
             for (k = 0; k < i; ++k)
               A[i][j] -= A[i][k] * A[k][j];

         Optimized:
           - Interchange the j and k loops to get a rank-1 update:
               for (k = 0; k < i; ++k) {
                 aik = A[i][k];
                 for (j = i; j < N; ++j)
                   A[i][j] -= aik * A[k][j];
               }
           - For a fixed (i,j), the sequence of subtractions over k
             is still performed in increasing k order, exactly as in
             the original code; only the interleaving across different
             j values changes, which does not affect the per-element
             result.
           - This loop order makes both A[i][j] and A[k][j]
             accesses contiguous along j, improving cache behavior. */
      for (k = 0; k < i; k++)
        {
          DATA_TYPE aik = A[i][k];
          for (j = i; j < _PB_N; j++)
            A[i][j] -= aik * A[k][j];
        }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
