#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization.
 *
 * The original structure is preserved, but the Gram matrix formation
 * (the "make the matrix positive semi-definite" part) is rewritten
 * for better cache locality and fewer memory writes.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Precompute 1/n once to avoid repeated divisions. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  /* Local restrict-qualified view to help the compiler with aliasing. */
  DATA_TYPE (*restrict A_)[n] = A;

  /* Build an initial lower-triangular-like matrix. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
        /* Original formula: (DATA_TYPE)(-j % n) / n + 1
         * is algebraically equivalent to:
         *    ((DATA_TYPE)(-j % n)) * inv_n + 1.0
         */
        Ai[j] = ((DATA_TYPE)(-j % n)) * inv_n + (DATA_TYPE)1.0;

      for (j = i+1; j < n; j++)
        Ai[j] = (DATA_TYPE)0;

      /* Set diagonal to 1 as in original code. */
      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite.
   * This computes B = A * A^T and then copies B back into A.
   * Compared to the original code:
   *  - We eliminate the explicit zero-initialization of B.
   *  - We compute each B[r][s] as a single dot-product over t,
   *    improving cache locality (t is innermost, accessing A rows
   *    contiguously) and reducing memory traffic to B.
   *  - The mathematical result is identical:
   *        B[r][s] = sum_t A[r][t] * A[s][t]
   */

  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);
  DATA_TYPE (*restrict Aview)[n] = A_; /* just a more descriptive alias */

  /* Compute B = A * A^T in a cache-friendly way: r,s outer; t inner. */
  for (r = 0; r < n; ++r) {
    DATA_TYPE *restrict Br = B_[r];
    const DATA_TYPE *restrict Ar = Aview[r];

    for (s = 0; s < n; ++s) {
      const DATA_TYPE *restrict As = Aview[s];
      DATA_TYPE sum = (DATA_TYPE)0;

      /* Dot product of row r and row s of A:
       *   sum_{t=0}^{n-1} A[r][t] * A[s][t]
       */
      for (t = 0; t < n; ++t)
        sum += Ar[t] * As[t];

      Br[s] = sum;
    }
  }

  /* Copy B back into A.  Using memcpy by row improves performance
   * over element-wise copying and preserves exact values.
   */
  for (r = 0; r < n; ++r) {
    DATA_TYPE *restrict Ar = Aview[r];
    DATA_TYPE *restrict Br = B_[r];
    memcpy(Ar, Br, (size_t)n * sizeof(DATA_TYPE));
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel: in-place LU decomposition without pivoting.
 * The whole function is timed.
 *
 * Optimizations applied:
 *  - Introduce restrict-qualified pointer to the matrix to aid alias analysis.
 *  - Use row pointers (Ai, Ak) to avoid repeated address arithmetic.
 *  - Compute the "L" part using a local accumulator variable `sum`
 *    instead of repeatedly updating A[i][j] in memory.
 *  - Reorder the update for the "U" part to use a rank-1 style update:
 *        for (k) for (j) A[i][j] -= L[i][k]*U[k][j]
 *    This preserves the exact sequence of arithmetic operations per
 *    element A[i][j] compared to the original code, but improves
 *    spatial locality: inner loop walks along contiguous memory in `j`.
 *  - Add a GCC-specific ivdep pragma on the innermost j-loop to hint
 *    that iterations are independent and can be vectorized.
 */
static
void kernel_lu [[gnu::flatten, gnu::noinline]] (int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified view of A.
   * The dimension uses the runtime parameter n; PolyBench guarantees
   * that _PB_N <= n, so all indexed accesses remain in-bounds.
   */
  const int n_ = n;
  DATA_TYPE (*restrict A_)[n_] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute L(i,0..i-1): lower-triangular elements of row i. */
    for (j = 0; j < i; j++) {
      /* Start from the current A[i][j] and subtract the dot product
       * over k = 0..j-1: sum_k L[i][k] * U[k][j].
       *
       * Using a local accumulator keeps A[i][j] in a register for the
       * whole inner loop, reducing memory traffic.
       */
      DATA_TYPE sum = Ai[j];

      for (k = 0; k < j; k++) {
        sum -= Ai[k] * A_[k][j];
      }

      /* Divide by U[j][j], as in the original code. */
      sum /= A_[j][j];
      Ai[j] = sum;
    }

    /* Update U(i,i..end): upper-triangular elements of row i.
     *
     * Original code:
     *   for (j = i; j < _PB_N; j++)
     *     for (k = 0; k < i; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *
     * Here we reorder the loops as:
     *   for (k = 0; k < i; k++)
     *     for (j = i; j < _PB_N; j++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *
     * For any fixed (i,j), the sequence of subtractions over k
     * (k = 0..i-1) is identical to the original, so the arithmetic
     * operations performed for each A[i][j] are the same and in
     * the same order. The only change is the traversal order in
     * memory, which is now friendlier to caches and SIMD:
     *  - inner loop walks over contiguous columns j of rows i and k.
     */
    for (k = 0; k < i; k++) {
      const DATA_TYPE Lik = Ai[k];         /* L[i][k], already computed */
      const DATA_TYPE *restrict Ak = A_[k];

      /* Hint to GCC that different iterations over j are independent
       * (for a fixed i,k) and can be safely vectorized.
       */
#pragma GCC ivdep
      for (j = i; j < _PB_N; j++) {
        Ai[j] -= Lik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
