   * cache locality and enable more efficient vectorization.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T (Gram matrix).
   *
   * Original code:
   *   B[r][s] = 0;
   *   for t:
   *     B[r][s] += A[r][t] * A[s][t];
   *
