   *   for r, s:
   *     sum = 0;
   *     for t:
   *       sum += A[r][t] * A[s][t];
   *     B[r][s] = sum;
   *
   * This accesses rows of A contiguously in the inner loop,
   * which is much more cache friendly.
   */
