    for (s = 0; s < n; ++s)
    {
      DATA_TYPE sum = (DATA_TYPE)0;

      /* Dot product of row r and row s of A. */
      for (t = 0; t < n; ++t)
      {
        sum += A[r][t] * A[s][t];
      }

      Br[s] = sum;
    }
  }

  /* Copy B back into A.
   * Using memcpy exploits contiguous row layout.
   */
#if defined(_OPENMP)
#pragma omp parallel for if (n >= LU_INIT_OMP_MIN_N) private(s) schedule(static)
#endif
  for (r = 0; r < n; ++r)
  {
    DATA_TYPE *restrict Br = B_[r];
    DATA_TYPE *restrict Ar = A[r];

