/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static void __attribute__((noinline, flatten))
kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Precompute and reuse 1 / A[j][j] for many rows.
   * diag_inv[j] is set after row j is fully computed (when A[j][j] is final)
   * and is used for all subsequent rows i > j when computing L(i,j).
   * This replaces expensive divisions with cheaper multiplications.
   */
  DATA_TYPE diag_inv[n];

#pragma scop
#if defined(_OPENMP)
  /* Parallelize across columns (U-part) for each row.
   * The L-part (j < i) has loop-carried dependencies in j and is
   * therefore computed by a single thread. The U-part (j >= i) has
   * independent columns and is safely parallelized with omp for.
   *
   * When compiled without -fopenmp, all OpenMP pragmas are ignored and
   * this reduces to the original sequential algorithm.
   */
#pragma omp parallel if (_PB_N >= LU_KERNEL_OMP_MIN_N) default(none) shared(A, diag_inv, n) private(i,j,k)
#endif
  {
    for (i = 0; i < _PB_N; i++) {
      DATA_TYPE *restrict Ai = A[i];

      /* 1. Compute L(i, j) for j < i.
       *    L(i,j) = (A[i][j] - sum_{k<j} L(i,k)*U(k,j)) / U(j,j)
       *
       * Dependencies along j (each L(i,j) uses previously computed
       * L(i,0..j-1)) prevent parallelization, so we keep this part
       * strictly sequential (one thread via omp single).
       */
#if defined(_OPENMP)
#pragma omp single
#endif
      {
        for (j = 0; j < i; j++) {
          DATA_TYPE sum = Ai[j];

          /* Dot product: sum -= sum_{k=0}^{j-1} L(i,k)*U(k,j). */
          for (k = 0; k < j; k++) {
            sum -= Ai[k] * A[k][j];
          }

          /* Divide by U(j,j) using its precomputed inverse. */
          Ai[j] = sum * diag_inv[j];
        }
      } /* implicit barrier at end of single when OpenMP is enabled */

      /* 2. Compute U(i, j) for j >= i.
       *    U(i,j) = A[i][j] - sum_{k<i} L(i,k)*U(k,j)
       *
       * Each column j is independent given the already computed L(i,*),
       * so we parallelize this over j with OpenMP when enabled.
       */
#if defined(_OPENMP)
#pragma omp for schedule(static)
#endif
      for (j = i; j < _PB_N; j++) {
        DATA_TYPE sum = Ai[j];

        for (k = 0; k < i; k++) {
          sum -= Ai[k] * A[k][j];
        }

        Ai[j] = sum;
      } /* implicit barrier at end of for when OpenMP is enabled */

      /* 3. Precompute inverse of the new diagonal U(i,i) for
       *    use in later rows (i' > i) when computing L(i', i).
       */
#if defined(_OPENMP)
#pragma omp single
#endif
      {
        diag_inv[i] = ((DATA_TYPE)1) / Ai[i];
      }

#if defined(_OPENMP)
      /* Ensure diag_inv[i] is visible before the next iteration uses it. */
#pragma omp barrier
#endif
    }
  }
#pragma endscop
}


